/* REV189 — CTA-driven logo stencil, rising curtain + native hero parallax.
   Authentic underlying hero, no duplicated asset, no autonomous movie. */
window.DavideIntro177=(function(){
 'use strict';
 const entry=document.getElementById('home139-entry');
 const canvas=document.getElementById('rev179-morph-film');
 const enter=entry?.querySelector('.rev189-enter');
 if(!entry||!canvas)return {begin(){},reveal(cb){cb?.()},endImmediately(){}};
 const ctx=canvas.getContext('2d',{alpha:true});
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const DURATION=860; // Matches menu opening (REV169: 860ms).
 const stencil=new Image();
 stencil.decoding='async';
 stencil.src='data:image/png;base64,';
 let stencilReady=false;
 let active=false,finished=false,curtainAnimation=null,heroAnimation=null,done=null;
 const clamp=x=>Math.max(0,Math.min(1,x));
 const smooth=x=>{x=clamp(x);return x*x*(3-2*x)};
 const MENU_EASING='cubic-bezier(.23,.74,.25,1)'; // Same as the menu curtain.
 stencil.onload=()=>{stencilReady=true;if(!active&&!finished)drawStencil()};
 stencil.onerror=()=>{stencilReady=false;if(!active&&!finished)drawStencil()};
 function realHeroSlides(){return document.querySelector('#app .home139-hero .home139-slides')}
 function currentHeroImage(){
   return document.querySelector('#app .home139-hero .home139-slide.is-active') ||
     document.querySelector('#app .home139-hero .home139-slide') ||
     document.querySelector('#app .home139-hero img');
 }
 async function awaitHero(){
   const img=currentHeroImage();
   if(!img || img.complete)return;
   await Promise.race([
     new Promise(r=>{img.addEventListener('load',r,{once:true});img.addEventListener('error',r,{once:true})}),
     new Promise(r=>setTimeout(r,1500))
   ]);
 }
 function drawStencil(){
   if(!ctx)return;
   const w=Math.max(1,innerWidth),h=Math.max(1,innerHeight);
   const ratio=Math.max(.5,Math.min(devicePixelRatio||1,1.65,1900/w));
   canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio);
   ctx.setTransform(canvas.width/w,0,0,canvas.height/h,0,0);
   ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;
   ctx.clearRect(0,0,w,h);ctx.fillStyle='#050505';ctx.fillRect(0,0,w,h);
   if(stencilReady){
     /* Approximately 30% smaller on desktop; gently reduced on mobile. */
     const lw=Math.min(w*(w<=680?.72:.58),520),lh=lw*490/1600;
     const x=(w-lw)/2,y=(h-lh)/2;
     ctx.globalCompositeOperation='destination-out';
     ctx.drawImage(stencil,x,y,lw,lh);
     ctx.globalCompositeOperation='source-over';
   }else{
     ctx.save();ctx.globalCompositeOperation='destination-out';
     ctx.fillStyle='#fff';ctx.textAlign='center';ctx.textBaseline='middle';
     const fs=Math.min(w*.079,70);
     ctx.font='700 '+fs+'px Jost, sans-serif';
     ctx.fillText('DAVIDE',w/2,h/2-fs*.15);
     ctx.font='700 '+Math.max(13,fs*.34)+'px Jost, sans-serif';
     ctx.fillText('CASTELMEZZANO',w/2,h/2+fs*.60);
     ctx.restore();
   }
   // REV197: the opaque first-paint guard must not be removed before the
   // native Hero and the name stencil are both ready for their first frame.
   if (!entry.classList.contains('rev197-painted') &&
       !document.body.classList.contains('site-booting') &&
       document.querySelector('#app .home139-hero')) {
     requestAnimationFrame(() => {
       if (!entry.hidden && document.querySelector('#app .home139-hero')) {
         entry.classList.add('rev197-painted');
       }
     });
   }
 }
 function interfaceReveal(p){
   document.body.style.setProperty('--rev185-home-ui-opacity',String(smooth((p-.46)/.49)));
 }
 function cleanupHero(){
   const host=realHeroSlides();
   if(heroAnimation){heroAnimation.cancel();heroAnimation=null;}
   if(host){host.style.animation='';host.style.transform='';host.style.filter='';host.style.transition='';}
 }
 function complete(){
   if(finished)return;
   finished=true;active=false;
   interfaceReveal(1);
   const cb=done;done=null;
   cb?.(); // Removes entry-active class before restoring wrapper to native CSS scale.
   cleanupHero();
   canvas.style.webkitMaskImage='';canvas.style.maskImage='';
 }
 function endImmediately(){
   if(curtainAnimation){curtainAnimation.cancel();curtainAnimation=null;}
   canvas.style.transform='translate3d(0,-100%,0)';
   complete();
 }
 function begin(){
   if(curtainAnimation){curtainAnimation.cancel();curtainAnimation=null;}
   cleanupHero();
   active=false;finished=false;done=null;
   canvas.style.transform='translate3d(0,0,0)';
   canvas.style.filter='';canvas.style.maskImage='';canvas.style.webkitMaskImage='';
   entry.classList.remove('rev189-leaving','rev187-revealing','intro177-evaporating');
   enter?.removeAttribute('disabled');
   interfaceReveal(0);drawStencil();
 }
 async function reveal(cb){
   if(finished){cb?.();return;}
   if(active)return;
   active=true;done=cb;
   entry.classList.add('rev189-leaving');
   enter?.setAttribute('disabled','');
   if(reduced.matches){endImmediately();return;}
   await awaitHero();
   if(finished)return;
   // Soften only the moving bottom edge of the curtain. The stencil stays cut out.
   const softEdge='linear-gradient(to bottom, #000 0%, #000 88%, transparent 100%)';
   canvas.style.maskImage=softEdge;
   canvas.style.webkitMaskImage=softEdge;
   // The original hero, not an image copy, breathes through the letters while idle.
   // On entry the wrapper settles smoothly to native transform scale(1).
   const host=realHeroSlides();
   if(host){
     const from=getComputedStyle(host).transform;
     host.style.animation='none';host.style.transform=from==='none'?'scale(.976)':from;
     if(host.animate){
       heroAnimation=host.animate([
         {transform:from==='none'?'scale(.976)':from,filter:'blur(0px)'},
         {transform:'scale(.988)',filter:'blur(0.8px)',offset:.33},
         {transform:'scale(1)',filter:'blur(0px)'}
       ],{duration:DURATION,easing:MENU_EASING,fill:'forwards'});
     }else{
       host.style.transition='transform '+DURATION+'ms ease,filter '+DURATION+'ms ease';
       requestAnimationFrame(()=>{host.style.transform='scale(1)';host.style.filter='blur(0px)'});
     }
   }
   // Curtain opens from bottom to top. Blur fades into focus at the end, no cut.
   if(canvas.animate){
     curtainAnimation=canvas.animate([
       {transform:'translate3d(0,0,0)',filter:'blur(0px)'},
       {transform:'translate3d(0,-34%,0)',filter:'blur(0.6px)',offset:.44},
       {transform:'translate3d(0,-100%,0)',filter:'blur(0px)'}
     ],{duration:DURATION,easing:MENU_EASING,fill:'forwards'});
     const began=performance.now();
     const frame=(now)=>{
       if(!active||finished)return;
       interfaceReveal((now-began)/DURATION);
       if(now-began<DURATION)requestAnimationFrame(frame);
     };
     requestAnimationFrame(frame);
     curtainAnimation.finished.then(()=>{
       if(finished)return;
       canvas.style.transform='translate3d(0,-100%,0)';
       curtainAnimation.cancel();curtainAnimation=null;
       requestAnimationFrame(()=>requestAnimationFrame(complete));
     }).catch(()=>{});
   }else{
     canvas.style.transition='transform '+DURATION+'ms '+MENU_EASING;
     requestAnimationFrame(()=>{canvas.style.transform='translate3d(0,-100%,0)'});
     let started=performance.now();
     const step=now=>{if(!active||finished)return;interfaceReveal((now-started)/DURATION);if(now-started<DURATION)requestAnimationFrame(step)};
     requestAnimationFrame(step);
     setTimeout(complete,DURATION+50);
   }
 }
 addEventListener('resize',()=>{if(!active&&!finished)drawStencil()},{passive:true});
 entry.setAttribute('aria-label','Davide Castelmezzano. Attraverso il nome si vede la pittura. Premi Entra per accedere al sito.');
 return {begin,reveal,endImmediately};
})();
